// Simple Pixel Dodger game
// Canvas element with id="game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;

  // Player configuration
  const player = { x: width / 2 - 10, y: height - 30, size: 20, speed: 4, color: '#000' };
  const keys = {};

  // Shape configuration
  const shapes = [];
  const shapeSize = 20;
  const spawnInterval = 800; // ms
  let lastSpawn = 0;
  let score = 0;
  let gameOver = false;

  // Input handling
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  function spawnShape() {
    const x = Math.random() * (width - shapeSize);
    const isGreen = Math.random() < 0.4; // 40% green, else red
    shapes.push({ x, y: -shapeSize, size: shapeSize, color: isGreen ? 'green' : 'red', isGreen, speed: 2 + Math.random() * 2 });
  }

  function update(dt) {
    // player movement
    if (keys.ArrowLeft) player.x -= player.speed;
    if (keys.ArrowRight) player.x += player.speed;
    if (keys.ArrowUp) player.y -= player.speed;
    if (keys.ArrowDown) player.y += player.speed;
    // keep player in bounds
    player.x = Math.max(0, Math.min(width - player.size, player.x));
    player.y = Math.max(0, Math.min(height - player.size, player.y));

    // spawn new shapes
    if (performance.now() - lastSpawn > spawnInterval) {
      spawnShape();
      lastSpawn = performance.now();
    }

    // update shapes
    for (let i = shapes.length - 1; i >= 0; i--) {
      const s = shapes[i];
      s.y += s.speed;
      // collision with player
      if (
        s.x < player.x + player.size &&
        s.x + s.size > player.x &&
        s.y < player.y + player.size &&
        s.y + s.size > player.y
      ) {
        if (s.isGreen) {
          score++;
          shapes.splice(i, 1);
          continue;
        } else {
          gameOver = true;
        }
      }
      // shape reaches bottom
      if (s.y > height) {
        gameOver = true;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // draw player
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.size, player.size);
    // draw shapes
    shapes.forEach(s => {
      ctx.fillStyle = s.color;
      ctx.fillRect(s.x, s.y, s.size, s.size);
    });
    // draw score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', width / 2 - 60, height / 2);
    }
  }

  let lastTime = 0;
  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    if (!gameOver) update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
